#include "midi/DeviceProfile.h"
#include <algorithm>
#include <cctype>
namespace jeff::daw { DecodedEventBatch DeviceProfile::decode(const MidiMessage&m,std::int64_t t)const noexcept{DecodedEventBatch b;switch(m.type){case MidiType::noteOn:b.events[0]=PerformanceEvent::noteOn(0,m.data1,m.value,t,m.channel);b.size=1;break;case MidiType::noteOff:b.events[0]=PerformanceEvent::noteOff(0,m.data1,t,m.channel);b.size=1;break;case MidiType::pressure:b.events[0]=PerformanceEvent::expression(0,m.channel,m.data1,ExpressionKind::pressure,m.value,0,t);b.size=1;break;case MidiType::pitch:b.events[0]=PerformanceEvent::expression(0,m.channel,m.data1,ExpressionKind::pitch,m.value,0,t);b.size=1;break;case MidiType::cc:if(m.data1==74){b.events[0]=PerformanceEvent::expression(0,m.channel,0,ExpressionKind::timbre,m.value,0,t);b.size=1;}break;default:break;}return b;} const DeviceProfile&ProfileRegistry::match(const DeviceIdentity&i)const noexcept{auto n=i.name;std::transform(n.begin(),n.end(),n.begin(),[](unsigned char c){return(char)std::tolower(c);});if(n.find("orba 2")!=std::string::npos)return orba2;if(n.find("orba")!=std::string::npos)return orba1;if(n.find("jt-4000")!=std::string::npos||n.find("jt4000")!=std::string::npos)return jt;return generic;} }
